{"page": {"kind": "content", "eyebrow": null, "headline": "学习率 η：0.01~0.5 范围内的收敛行为对比", "lead": "学习率 η 控制梯度下降每一步的步长，是影响收敛行为的关键超参数。"}, "brief": {"objective": "学生能复述本页核心结论", "keyClaim": "学习率 η：0.01~0.5 范围内的收敛行为对比", "misconception": "", "visualTask": "视觉直接编码本页核心关系", "evidencePolicy": "none"}, "siblingPlan": [{"id": "lr-sim", "type": "sim", "role": "visualization", "intent": "让学生通过滑块调节三条轨迹的学习率，实时观察不同学习率下梯度下降在 f(x)=x² 上的收敛行为，直观理解过大/过小学习率的影响。", "size": "l"}, {"id": "lr-callout", "type": "callout", "role": "support", "intent": "总结学习率选择的经验法则：过大导致震荡发散，过小导致收敛极慢，需折中选择。", "size": "s"}]}
